#!/usr/bin/env bash
workflow_steps_load() {
  local manifest="$1" validation
  validation="$(jq -er 'def bad($m): error($m); .steps as $s | if type!="object" or ($s|type)!="array" or (.workflowArcRetired|type)!="array" then bad("invalid workflow manifest") elif ($s|length)==0 then bad("workflow steps are empty") elif (($s|map(.name)|unique|length)!=($s|length)) then bad("duplicate workflow step") else . end | $s[] | .name as $n | if (.name|type)!="string" or .name=="" then bad("invalid workflow step name") elif (.runBy=="runner" or .runBy=="board")|not then bad($n+": invalid runBy") elif ([.runsModel,.writesStatus,.receivesConflict,.runsTests,.runsReview,.takesSlot,.ownRow,.phaseControl,.dependencyGated]|all(type=="boolean"))|not then bad($n+": missing or invalid boolean field") elif (.phaseOrder!=null and ((.phaseOrder|type)!="number" or .phaseOrder<=0)) then bad($n+": invalid phaseOrder") else true end' "$manifest" 2>&1)" || { printf '%s\n' "$validation" >&2; return 1; }
  WORKFLOW_STEPS="$(jq -r '[.steps[]|select(.runBy=="runner")|.name]|join(" ")' "$manifest")"; BOARD_STEPS="$(jq -r '[.steps[]|select(.runBy=="board")|.name]|join(" ")' "$manifest")"
  DEPENDENCY_GATED_STEPS="$(jq -r '[.steps[]|select(.dependencyGated)|.name]|join(" ")' "$manifest")"; WORKFLOW_ARC="$(jq -r '[.steps[]|select(.phaseOrder!=null)]|sort_by(.phaseOrder)|map(.name)|join(" ")' "$manifest")"
  PHASE_STEPS="$(jq -r '[.steps[]|select(.phaseControl)]|sort_by(.phaseOrder)|map(.name)|join(" ")' "$manifest")"; WORKFLOW_ARC_RETIRED="$(jq -r '.workflowArcRetired|join(" ")' "$manifest")"; WORKFLOW_STEPS_FILE="$manifest"
}
workflow_step_resolve() { local row; row="$(jq -ec --arg name "$1" '.steps[]|select(.name==$name)' "$WORKFLOW_STEPS_FILE")" || return 1; STEP_RUN_BY="$(jq -r .runBy <<<"$row")"; STEP_RUNS_MODEL="$(jq -r .runsModel <<<"$row")"; STEP_WRITES_STATUS="$(jq -r .writesStatus <<<"$row")"; STEP_RECEIVES_CONFLICT="$(jq -r .receivesConflict <<<"$row")"; STEP_RUNS_TESTS="$(jq -r .runsTests <<<"$row")"; STEP_RUNS_REVIEW="$(jq -r .runsReview <<<"$row")"; STEP_TAKES_SLOT="$(jq -r .takesSlot <<<"$row")"; STEP_OWN_ROW="$(jq -r .ownRow <<<"$row")"; STEP_PHASE_ORDER="$(jq -r '.phaseOrder//empty' <<<"$row")"; STEP_PHASE_CONTROL="$(jq -r .phaseControl <<<"$row")"; STEP_DEPENDENCY_GATED="$(jq -r .dependencyGated <<<"$row")"; }
